const {chromium} = require('playwright');
const OUT = process.argv[2];
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({viewport: {width: 1100, height: 950}, deviceScaleFactor: 1});
  const errs = [];
  p.on('pageerror', e => errs.push('pageerror: ' + e.message));
  p.on('console', m => { if (m.type() === 'error') errs.push('console: ' + m.text()); });
  await p.goto('http://127.0.0.1:8765/index.html');
  await p.evaluate(() => { localStorage.clear(); sessionStorage.clear(); });
  await p.reload();
  await p.waitForTimeout(500);
  const shot = async n => { await p.waitForTimeout(450); await p.locator('#phone').screenshot({path: `${OUT}/${n}.png`}); };
  const click = async (sel, i = 0) => { const ok = await p.evaluate(([s, i]) => { const l = [...document.querySelectorAll('#phone .layer:last-of-type ' + s)]; const e = l[i] || [...document.querySelectorAll('#phone ' + s)][i]; if (!e) return false; e.click(); return true; }, [sel, i]); if (!ok) errs.push('missing ' + sel + ' #' + i); await p.waitForTimeout(350); };
  const scroll = async y => { await p.evaluate(y => { const l = [...document.querySelectorAll('#phone .layer')].pop(); const s = l.querySelector('.scroll,.hbody'); s.scrollTop = y; s.dispatchEvent(new Event('scroll')); }, y); await p.waitForTimeout(500); };
  await click('.hs[data-act="tab:stores"]');
  await shot('01_feed');
  await scroll(700); await shot('02_feed_scrolled');
  await scroll(1500); await shot('03_feed_band_b');
  await scroll(0);
  await click('.st-lens button[data-v="offers"]'); await shot('04_offers');
  await click('.st-tiles button', 1); await shot('05_offers_food');
  await click('.st-types .st-chip[data-v="b11"]'); await shot('06_offers_food_11');
  await click('.st-subs .st-chip', 2); await shot('07_sub_l2');
  await click('.st-subs .st-chip', 1); await shot('08_sub_l3');
  await click('.st-lens button[data-v="cash"]'); await shot('09_cash');
  await click('.st-lens button[data-v="vouch"]'); await shot('10_vouch');
  await click('.st-switch'); await shot('11_vouch_all');
  await click('.st-sort'); await shot('12_sort_sheet');
  await click('.st-opts li', 1); await shot('13_sorted');
  await click('.st-filter'); await shot('14_filter_sheet');
  await click('.st-seg[data-key="ch"] button', 2); await shot('15_filter_online');
  await click('[data-go]'); await shot('16_filtered');
  console.log(errs.join('\n') || 'no errors');
  await b.close();
})();
